```js
function newArrivalsFeed(limit=8){
  const isIn = p => INNERWEAR_CATS.includes(p.category);
  const isNew = p => Array.isArray(p.tags) && p.tags.includes('new');
  const men  = DB.products.filter(p=>p.category==='mens-underwear');
  const women= DB.products.filter(p=>p.category==='womens-underwear');
  const pick = list => list.filter(isNew).concat(list.filter(p=>!isNew(p)));
  const m = pick(men), w = pick(women);
  /* Alternate men's and women's innerwear so both lines share the eight slots
     equally (4 + 4), then fall back to the rest of the store if either line
     ever runs short. */
  const inner = [];
  for(let i=0; i<Math.max(m.length,w.length); i++){
