    if(w[i]) inner.push(w[i]);
  }
  const rest = DB.products.filter(p=>!isIn(p) && isNew(p)).concat(DB.products.filter(p=>!isIn(p) && !isNew(p)));
  return [...inner, ...rest].slice(0, limit);
}
