/* Picks `limit` products spread across as many different sub-categories as
   possible: one product per sub-category per round, keeping the candidate
   order, so a rail never fills up with a single category. */
function diverseFeed(candidates, limit){
  const byCat = {};
  candidates.forEach(p => (byCat[p.category] = byCat[p.category] || []).push(p));
  const cats = Object.keys(byCat);
  const out = [];
  let i = 0;
  while(out.length < limit && cats.some(c => byCat[c].length)){
    const bucket = byCat[cats[i % cats.length]];
    const item = bucket.shift();
    if(item) out.push(item);
    i++;
  }
  return out;
}
```

